mapper.select:
SELECT id, order_no, user_id, session_id, status, expire_at, created_at, updated_at
FROM ticket_order
WHERE id = #{orderId}

SELECT id, order_no, user_id, session_id, status, expire_at, created_at, updated_at
FROM ticket_order
WHERE id = #{orderId}
  AND user_id = #{userId}

mapper.update:
UPDATE ticket_order
SET status = 'PAID',
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{orderId}
  AND user_id = #{userId}
  AND status = 'WAIT_PAY'
  AND expire_at > #{paymentNow}

UPDATE ticket_order
SET status = 'CANCELLED',
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{orderId}
  AND user_id = #{userId}
  AND status = 'WAIT_PAY'

UPDATE ticket_order
SET status = 'REFUNDED',
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{orderId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND status = 'PAID'

mapper.select:
SELECT id
FROM ticket_order
WHERE status = 'WAIT_PAY'
  AND expire_at <= #{scanNow}
ORDER BY expire_at ASC, id ASC
LIMIT #{batchSize}

mapper.update:
UPDATE ticket_order
SET status = 'CLOSED',
    updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{orderId}
  AND status = 'WAIT_PAY'
  AND expire_at <= #{scanNow}
